let semgrepResults = $input.first().json.body.results || [];

// Humne auditLog ko update kiya hai taake wo sirf "PASS/FAIL" nahi, balke details bhi store kare
let auditLog = {
  "A.8.24 (Cryptography/Secrets)": { status: "PASS", details: "-" },
  "A.8.28 (Secure Coding/Injection)": { status: "PASS", details: "-" },
  "A.8.4 (Access to Source Code)": { status: "PASS", details: "-" },
  "A.8.8 (Vulnerability Management)": { status: "PASS", details: "-" },
  "A.8.9 (Configuration Management)": { status: "PASS", details: "-" }
};

for (let finding of semgrepResults) {
  let checkId = finding.check_id.toLowerCase();

  // Semgrep JSON se exact file, line aur remediation message nikal rahe hain
  let file = finding.path;
  let line = finding.start.line;
  let message = finding.extra.message;

  // Isko HTML format mein khoobsurat bana diya
  let failDetails = `<span style="font-size: 13px;"><b>File:</b> ${file} (Line ${line})<br><br><b>Fix:</b> ${message}</span>`;

  if (checkId.includes("secret") || checkId.includes("password") || checkId.includes("crypto")) {
    auditLog["A.8.24 (Cryptography/Secrets)"] = { status: "FAIL", details: failDetails };
  }

  if (checkId.includes("sql") || checkId.includes("injection") || checkId.includes("xss")) {
    auditLog["A.8.28 (Secure Coding/Injection)"] = { status: "FAIL", details: failDetails };
  }

  if (checkId.includes("mutable-action-tag") || checkId.includes("yaml")) {
    auditLog["A.8.9 (Configuration Management)"] = { status: "FAIL", details: failDetails };
  }
}

// Yahan Email Table design ho raha hai (ek naya column "Issue Details & Remediation" add kiya)
let emailBody = "<h3>Automated ISO 27001 Code Scan Results</h3>";
emailBody += "<p>New code was pushed to the repository. Here is the compliance mapping for the detected issues:</p>";
emailBody += "<table border='1' cellpadding='10' style='border-collapse: collapse; text-align: left; max-width: 800px;'>";
emailBody += "<tr style='background-color: #f3f4f6;'><th>ISO Control</th><th>Status</th><th>Issue Details & Remediation</th></tr>";

for (let [control, data] of Object.entries(auditLog)) {
  let color = data.status === "FAIL" ? "red" : "green";
  let statusText = `<span style='color: ${color}; font-weight: bold;'>${data.status}</span>`;

  emailBody += `<tr>
    <td style='white-space: nowrap;'><b>${control}</b></td>
    <td>${statusText}</td>
    <td>${data.details}</td>
  </tr>`;
}

emailBody += "</table>";
emailBody += "<br><p>Please fix the failing controls to maintain compliance.</p>";

return [{ json: { emailBody: emailBody } }];
